    "keyTooltip": {
      "sourceKey": "Spell_MaokaiPassive_Tooltip",
      "text": "茂凯的下一次攻击会回复自身<healing>@PassiveHealingTotal@生命值</healing>。<br><br>每施放一次技能或被一名敌方英雄的技能命中时，都会使这个冷却时间缩短@PassiveCooldownReduction@秒。被大型野怪或史诗级野怪的攻击或技能命中时，都会使这个冷却时间缩短@JungPassCooldownReduction@秒。"
    },
    "keySummary": {
      "sourceKey": "Spell_MaokaiPassive_Summary",
      "text": "茂凯的普通攻击也会治疗自身并造成额外伤害，此效果拥有一个中等的冷却时间。每当茂凯施放一次技能或被一个敌方技能击中时，这个冷却时间都会缩短。"
    },
    "keyCooldown": {
      "sourceKey": "Spell_Maokai_Cooldown",
      "text": "@PassiveCooldown@秒%i:cooldown%"
    }
  }
