    },
    "keySummary": {
      "sourceKey": "Spell_MaokaiE_Summary",
      "text": "茂凯投出一颗树苗去目标地区戒备。在草丛中更加有效。"
    },
    "keyTooltip": {
      "sourceKey": "Spell_MaokaiE_Tooltip",
      "text": "茂凯扔出一棵树苗，戒备@SaplingDuration@秒。树苗会追击附近的敌人，并在抵达后爆炸，对周围的敌人们造成<magicDamage>@TotalDamage@魔法伤害</magicDamage>和持续@SlowDuration@秒的@SlowAmount*100@%<status>减速</status>。如果树苗命中了一名敌方英雄或史诗级野怪，<keywordMajor>吸元秘术</keywordMajor>的冷却时间就会缩短额外的4秒。<br><br>投掷在草丛里的树苗会持续@EmpoweredSaplingDuration@秒，并引发一次范围更大的爆炸，在@EmpoweredDoTDuration@秒的持续时间里共造成<magicDamage>@TotalEmpoweredDamage@魔法伤害</magicDamage>并且<status>减速</status>幅度变为@EmpoweredSlowAmount@。"
    },
    "keyTooltipExtendedBelowLine": {
      "sourceKey": "Spell_MaokaiE_TooltipExtendedBelowLine",
      "text": "<rules>树苗以@SaplingMoveSpeed@速度进行奔跑。草丛树苗不会对小兵造成提升过的伤害。</rules>"
    }
  }
